template <class CharT>
struct CaseInsensitiveTraits {
    using char_type = CharT;
    using int_type = int;
    static constexpr int_type eof() { return -1; }

    static constexpr bool eq(char_type c1, char_type c2) {
        // Defines character equality check
        return std::tolower(c1) == std::tolower(c2);
    }

    static constexpr int_type to_int_type(char_type c) {
        return static_cast<int_type>(c);
    }
};

// Stream definition uses Traits as a policy
template <class CharT, class Traits>
class basic_istream {
    // Internally calls Traits::eq, Traits::eof, etc.
};

using CIStream = basic_istream<char, CaseInsensitiveTraits<char>>;
// CIStream will treat 'a' and 'A' as equal.
